const questions = [
  'Which doors must be fire-rated?',
  'List every requirement that applies to escape routes.',
  'What does the code say about corridor widths?'
];
return questions.map(q => ({ json: { question: q, mode: 'agentic' } }));

const rows = $input.all().map(item => {
  const a = item.json;
  const sources = (a.sources || []).length;
  const pass = Boolean(a.answer) && sources >= 1 && Boolean(a.coverage);
  return { question: a.mode, sources, coverage: a.coverage || null, pass };
});
const passed = rows.filter(r => r.pass).length;
return [{ json: { summary: `MS RAG Studio weekly eval: ${passed}/${rows.length} golden questions passed (answer + sources + coverage).`, rows } }];
